Your expense tracker is below: add what you spent, pick a category, and it keeps a running total, a budget check and a split by category. Entries stay only while this page is open, so don't close it before you've noted the totals.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:14px;background:#f6f7f5;color:#222}
h2{margin:0 0 10px;font-size:18px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0002}
.row{display:flex;gap:6px;flex-wrap:wrap}
input,select,button{font:inherit;padding:7px;border:1px solid #ccc;border-radius:6px}
input{flex:1;min-width:90px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
button.x{background:#c0392b;padding:3px 8px}
.big{font-size:24px;font-weight:600}
.bar{height:10px;background:#2f7d5b;border-radius:5px}
.track{background:#e4e8e5;border-radius:5px;margin:3px 0 8px}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.muted{color:#777;font-size:12px}
.over{color:#c0392b}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
<div class="row">
<input id="name" placeholder="What was it?">
<input id="amt" type="number" min="0" placeholder="Amount (₹)">
<select id="cat"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Fun</option><option>Other</option></select>
<button id="add">Add</button>
</div>
</div>
<div class="card">
<div class="muted">Total spent</div>
<div class="big" id="total">₹0</div>
<div class="row" style="margin-top:8px;align-items:center">
<span class="muted">Monthly budget (₹)</span>
<input id="budget" type="number" min="0" value="50000">
</div>
<div class="track"><div class="bar" id="bbar" style="width:0"></div></div>
<div id="left" class="muted"></div>
</div>
<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>Entries</b><div id="list"></div></div>
<script>
var items=[];
var $=function(i){return document.getElementById(i)};
function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
function render(){
var total=0,by={};
items.forEach(function(e){total+=e.a;by[e.c]=(by[e.c]||0)+e.a});
$("total").textContent=inr(total);
var b=Number($("budget").value)||0;
var pct=b>0?Math.min(100,total/b*100):0;
$("bbar").style.width=pct+"%";
var l=$("left");
if(b>0){
if(total>b){l.textContent="Over budget by "+inr(total-b);l.className="over"}
else{l.textContent=inr(b-total)+" left of "+inr(b);l.className="muted"}
}else{l.textContent="";}
var c=$("cats");c.textContent="";
Object.keys(by).sort(function(x,y){return by[y]-by[x]}).forEach(function(k){
var d=document.createElement("div");
var t=document.createElement("div");
t.textContent=k+": "+inr(by[k]);
var tr=document.createElement("div");tr.className="track";
var br=document.createElement("div");br.className="bar";
br.style.width=(total?by[k]/total*100:0)+"%";
tr.appendChild(br);d.appendChild(t);d.appendChild(tr);c.appendChild(d);
});
if(!items.length)c.textContent="Nothing yet.";
var L=$("list");L.textContent="";
items.slice().reverse().forEach(function(e){
var r=document.createElement("div");r.className="item";
var s=document.createElement("span");
s.textContent=e.n+" ("+e.c+") "+inr(e.a);
var x=document.createElement("button");x.className="x";x.textContent="Delete";
x.onclick=function(){items=items.filter(function(i){return i!==e});render()};
r.appendChild(s);r.appendChild(x);L.appendChild(r);
});
}
$("add").onclick=function(){
var a=Number($("amt").value);
if(!(a>0))return;
items.push({n:$("name").value.trim()||"Expense",a:a,c:$("cat").value});
$("name").value="";$("amt").value="";render();
};
$("budget").oninput=render;
render();
</script>
</body></html>
```
